questions.explanation:
## Why This Is Asked
Tests memory ownership across CGO, pre-allocated buffers, and concurrent calls—common in real bindings.

## Key Concepts
- Buffer ownership between Go and C
- CGO pointer passing and slicing of results
- Concurrency safety with shared C code
- Correct NUL handling and length reporting

## Code Example
```javascript
// C header (reverse_string.h)
size_t reverse_string(const char* input, char* output, size_t max_len);
```
```javascript
// Minimal C implementation (reverse_string.c)
#include <string.h>
#include <stddef.h>

size_t reverse_string(const char* input, char* output, size_t max_len) {
  size_t len = strlen(input);
  if (len >= max_len) len = max_len - 1;
  for (size_t i = 0; i < len; ++i) {
    output[i] = input[len - 1 - i];
  }
  output[len] = '\0';
  return len;
}
```
```javascript
// Go binding (cgobinding.go)
package main
/*
#include <stdlib.h>
#include "reverse_string.h"
*/
import "C"
import (
  "fmt"
  "unsafe"
)

func ReverseGo(s string) (string, error) {
  in := C.CString(s)
  defer C.free(unsafe.Pointer(in))
  buf := make([]byte, len(s)+1)
  written := C.reverse_string(in, (*C.char)(unsafe.Pointer(&buf[0])), C.size_t(len(buf)))
  if int(written) < 0 {
    return "", fmt.Errorf("reverse failed")
  }
  return string(buf[:written]), nil
}
```
```javascript
// Test program (main.go)
package main
import (
  "fmt"
  "sync"
)
func main() {
  var wg sync.WaitGroup
  inputs := []string{"abcdef", "12345"}
  for _, s := range inputs {
    wg.Add(1)
    go func(str string) {
      defer wg.Done()
      res, err := ReverseGo(str)
      if err != nil {
        fmt.Println("err:", err)
        return
      }
      fmt.Println("in:", str, "out:", res)
    }(s)
  }
  wg.Wait()
}
```

